void Step1()
{
    int[] parent;
    int[] size;

    int Solve(int[] X, int[] Y, int[] Z, int connectCount)
    {
        int n = X.Length;

        parent = new int[n];
        size = new int[n];

        for (int i = 0; i < n; i++)
        {
            parent[i] = i;
            size[i] = 1;
        }

        var edges = new List<(double dist, int a, int b)>();

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                double dx = X[i] - X[j];
                double dy = Y[i] - Y[j];
                double dz = Z[i] - Z[j];

                double d = Math.Sqrt(dx * dx + dy * dy + dz * dz);

                edges.Add((d, i, j));
            }
        }

        edges = edges.OrderBy(e => e.dist).ToList();

        for (int i = 0; i < connectCount && i < edges.Count; i++)
        {
            Union(edges[i].a, edges[i].b);
        }

        var groups = new Dictionary<int, int>();

        for (int i = 0; i < n; i++)
        {
            int root = Find(i);

            if (!groups.ContainsKey(root))
                groups[root] = 0;

            groups[root]++;
        }

        var biggest = groups.Values
                            .OrderByDescending(x => x)
                            .Take(3)
                            .ToList();

        if (biggest.Count == 1)
            return biggest[0];

        return biggest[0] * biggest[1] * biggest[2];
    }

    int Find(int x)
    {
        if (parent[x] == x)
            return x;

        parent[x] = Find(parent[x]);
        return parent[x];
    }

    void Union(int a, int b)
    {
        int ra = Find(a);
        int rb = Find(b);

        if (ra == rb) return;

        if (size[ra] < size[rb])
        {
            parent[ra] = rb;
            size[rb] += size[ra];
        }
        else
        {
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }

