        parent[x] = Find(parent[x]);
        return parent[x];
    }

    void Union(int a, int b)
    {
        int ra = Find(a);
        int rb = Find(b);

        if (ra == rb) return;

        if (size[ra] < size[rb])
        {
            parent[ra] = rb;
            size[rb] += size[ra];
        }
        else
        {
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }

